import path from 'path';
import os from 'os';
import {
  CLI_GUIDANCE_BODY,
  CLI_GUIDANCE_DESCRIPTION,
  CLI_GUIDANCE_VERSION,
} from '../utils/skills/cli-guidance';
import {
  hasAgentSkill,
  removeAgentSkill,
  writeAgentSkill,
  type AgentSkill,
  type SkillResult,
} from './agentSkill';

const CURSOR_SKILL_MARKER = '[//]: # (managed-by: rivet install cursor)';
const CURSOR_SKILL_CONTENT = `---
name: rivet
description: ${CLI_GUIDANCE_DESCRIPTION}
---

${CURSOR_SKILL_MARKER}
[//]: # (rivet-cli-guidance-version: ${CLI_GUIDANCE_VERSION})
# Rivet

${CLI_GUIDANCE_BODY}
`;

export const cursorSkillPath = (homeDir: string = os.homedir()): string =>
  path.join(homeDir, '.cursor', 'skills', 'rivet', 'SKILL.md');

const cursorSkill = (homeDir: string): AgentSkill => ({
  filePath: cursorSkillPath(homeDir),
  content: CURSOR_SKILL_CONTENT,
  marker: CURSOR_SKILL_MARKER,
});

export const hasCursorSkill = (homeDir: string = os.homedir()): boolean =>
  hasAgentSkill(cursorSkill(homeDir));

export const writeCursorSkill = (homeDir: string = os.homedir()): SkillResult =>
  writeAgentSkill(cursorSkill(homeDir));

export const removeCursorSkill = (
  homeDir: string = os.homedir(),
): SkillResult => removeAgentSkill(cursorSkill(homeDir));
